// Necessary five-port test with no shape restrictions. Input: record and graph6, one per line.
use std::io::{self,BufRead};
fn maximal(a:&[u32;27],mut p:u32,mut x:u32,s:u32,out:&mut Vec<u32>){if p|x==0{out.push(s);return}let pivot=(p|x).trailing_zeros() as usize;let mut w=p&!a[pivot];while w!=0{let b=w&w.wrapping_neg();w^=b;let i=b.trailing_zeros() as usize;maximal(a,p&a[i],x&a[i],s|b,out);p^=b;x|=b}}
fn five(g:&[Vec<usize>],opts:&[usize],k:usize)->bool{if k==1{return !opts.is_empty()}for(pos,&i)in opts.iter().enumerate(){if opts.len()-pos<k{break}let q:Vec<_>=g[i].iter().copied().filter(|v|opts[pos+1..].binary_search(v).is_ok()).collect();if five(g,&q,k-1){return true}}false}
fn main(){let k:usize=std::env::args().nth(1).map(|x|x.parse().unwrap()).unwrap_or(5);assert!(k==5||k==6);let f=(1<<27)-1;let mut tested=0;for l in io::stdin().lock().lines(){let l=l.unwrap();let(id,s)=l.split_once(' ').unwrap();let b=s.as_bytes();let mut a=[0u32;27];let mut t=0;for j in 0..27{for i in 0..j{if (b[1+t/6]-63)>>(5-t%6)&1==0{a[i]|=1<<j;a[j]|=1<<i}t+=1}}let mut rows=vec![];maximal(&a,f,0,0,&mut rows);let qs:Vec<_>=rows.iter().copied().filter(|s|s.count_ones()==7).collect();assert!(rows.iter().all(|s|s.count_ones()<=7));let n=rows.len();let w=(n+63)/64;let mut allowed=vec![vec![u64::MAX;w];n];for q in qs{let mut mask=vec![0;w];let mut missed=vec![];for(j,s)in rows.iter().enumerate(){if s&q==0{mask[j/64]|=1u64<<(j%64);missed.push(j)}}for j in missed{for k in 0..w{allowed[j][k]&=!mask[k]}}}let mut g=vec![vec![];n];for(i,r)in allowed.iter().enumerate(){assert_eq!(r[i/64]>>(i%64)&1,0);for k in i/64..w{let mut m=r[k];while m!=0{let j=k*64+m.trailing_zeros() as usize;m&=m-1;if j>i&&j<n{g[i].push(j)}}}}tested+=1;if five(&g,&(0..n).collect::<Vec<_>>(),k){println!("{}",id)}}eprintln!("{}",tested)}
